style.css:
@-moz-document domain("youtube.com") {
/* 1) Hide the original image(s) so nothing sits underneath */
  ytd-masthead ytd-yoodle-renderer picture,
  ytd-masthead ytd-yoodle-renderer img {
    display: none !important;
  }

  /* 2) Give the container a box the same size as the original (122×56) */
  ytd-masthead ytd-yoodle-renderer {
    display: inline-block !important;
    width: 122px !important;
    height: 56px !important;
    position: relative !important;
    vertical-align: middle !important;
  }

  /* 3) Draw only your image */
  ytd-masthead ytd-yoodle-renderer::before {
    content: "" !important;
    position: absolute !important;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background-image: url("https://i.imgur.com/2AjvavM.png") !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: contain !important;
    pointer-events: none !important; /* keep clicks behaving normally */
  }
}
